// Act2Revelation.cs
// Second mission: Act II - Revelation
// Uncovers deeper conspiracy, more complex hacking missions, moral choices
using FlaxEngine;
using System.Collections.Generic;
using System.Linq;

public class Act2Revelation : Mission
{
    // Objective descriptions for easy lookup
    private const string OBJ_INVESTIGATE_MARK_HQ = "Investigate the Mark Corporation headquarters";
    private const string OBJ_DECRYPT_RELAY_DATA = "Decode encrypted data from the relay station";
    private const string OBJ_ALLIANCE_DECISION = "Make a critical alliance decision with underground factions";
    private const string OBJ_INFILTRATE_BIO_FARM = "Infiltrate a biometric data farm";
    private const string OBJ_DATA_CHOICE = "Choose whether to expose, sell, or use the stolen data";
    private const string OBJ_ESCAPE_COUNTERMEASURES = "Escape increasing Mark system countermeasures";

    public override void OnStart()
    {
        base.OnStart();

        MissionID = "ACT2_REVELATION";
        MissionName = "Revelation";
        Description = "Uncover the deeper conspiracy behind the Mark system and make choices that will shape your path.";

        // Objectives will be initialized in InitializeObjectives
    }

    protected override void InitializeObjectives()
    {
        // Objective 1: Investigate Mark Corporation headquarters
        Objectives.Add(new MissionObjective
        {
            Description = OBJ_INVESTIGATE_MARK_HQ,
            IsOptional = false,
            TargetValue = 1
        });

        // Objective 2: Decode encrypted data from the relay station
        Objectives.Add(new MissionObjective
        {
            Description = OBJ_DECRYPT_RELAY_DATA,
            IsOptional = false,
            TargetValue = 1
        });

        // Objective 3: Make a critical alliance decision with underground factions
        Objectives.Add(new MissionObjective
        {
            Description = OBJ_ALLIANCE_DECISION,
            IsOptional = false,
            TargetValue = 1
        });

        // Objective 4: Infiltrate a biometric data farm
        Objectives.Add(new MissionObjective
        {
            Description = OBJ_INFILTRATE_BIO_FARM,
            IsOptional = false,
            TargetValue = 1
        });

        // Objective 5: Choose whether to expose, sell, or use the stolen data
        Objectives.Add(new MissionObjective
        {
            Description = OBJ_DATA_CHOICE,
            IsOptional = false,
            TargetValue = 1
        });

        // Objective 6: Escape increasing Mark system countermeasures
        Objectives.Add(new MissionObjective
        {
            Description = OBJ_ESCAPE_COUNTERMEASURES,
            IsOptional = false,
            TargetValue = 1
        });
    }

    protected override void UpdateMission()
    {
        base.UpdateMission();

        // Check for objective completions through game events and story flags
        CheckMarkHQInvestigation();
        CheckRelayDataDecryption();
        CheckAllianceDecision();
        CheckBioFarmInfiltration();
        CheckDataChoice();
        CheckEscapeCountermeasures();
    }

    private void CheckMarkHQInvestigation()
    {
        var objective = GetObjectiveByDescription(OBJ_INVESTIGATE_MARK_HQ);
        if (objective != null && !objective.IsComplete)
        {
            // Check if player has investigated Mark HQ via story flag
            var storyState = Scene.GetActor("StoryState")?.GetComponent<StoryState>();
            if (storyState != null && storyState.GetFlag("mark_hq_investigated"))
            {
                CompleteObjective(objective.ID);
                Debug.Log("��������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������Objective completed: Investigate the Mark Corporation headquarters");
            }
        }
    }

    private void CheckRelayDataDecryption()
    {
        var objective = GetObjectiveByDescription(OBJ_DECRYPT_RELAY_DATA);
        if (objective != null && !objective.IsComplete)
        {
            // Check if player has decrypted relay data via story flag
            var storyState = Scene.GetActor("StoryState")?.GetComponent<StoryState>();
            if (storyState != null && storyState.GetFlag("relay_data_decrypted"))
            {
                CompleteObjective(objective.ID);
                Debug.Log("������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������Objective completed: Decode encrypted data from the relay station");
            }
        }
    }

    private void CheckAllianceDecision()
    {
        var objective = GetObjectiveByDescription(OBJ_ALLIANCE_DECISION);
        if (objective != null && !objective.IsComplete)
        {
            // Check if player has made alliance decision via story flags
            var storyState = Scene.GetActor("StoryState")?.GetComponent<StoryState>();
            if (storyState != null &&
                (storyState.GetFlag("alliance_with_resistance") ||
                 storyState.GetFlag("alliance_with_corporate_remnants") ||
                 storyState.GetFlag("alliance_remained_independent")))
            {
                CompleteObjective(objective.ID);
                Debug.Log("����������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������Objective completed: Make a critical alliance decision with underground factions");
            }
        }
    }

    private void CheckBioFarmInfiltration()
    {
        var objective = GetObjectiveByDescription(OBJ_INFILTRATE_BIO_FARM);
        if (objective != null && !objective.IsComplete)
        {
            // Check if player has infiltrated bio farm via story flag
            var storyState = Scene.GetActor("StoryState")?.GetComponent<StoryState>();
            if (storyState != null && storyState.GetFlag("bio_farm_infiltrated"))
            {
                CompleteObjective(objective.ID);
                Debug.Log("����������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������Objective completed: Infiltrate a biometric data farm");
            }
        }
    }

    private void CheckDataChoice()
    {
        var objective = GetObjectiveByDescription(OBJ_DATA_CHOICE);
        if (objective != null && !objective.IsComplete)
        {
            // Check if player has made data choice via story flags
            var storyState = Scene.GetActor("StoryState")?.GetComponent<StoryState>();
            if (storyState != null &&
                (storyState.GetFlag("data_exposed") ||
                 storyState.GetFlag("data_sold") ||
                 storyState.GetFlag("data_used")))
            {
                CompleteObjective(objective.ID);
                Debug.Log("��������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������Objective completed: Choose whether to expose, sell, or use the stolen data");
            }
        }
    }

    private void CheckEscapeCountermeasures()
    {
        var objective = GetObjectiveByDescription(OBJ_ESCAPE_COUNTERMEASURES);
        if (objective != null && !objective.IsComplete)
        {
            // Check if player has escaped countermeasures via story flag
            var storyState = Scene.GetActor("StoryState")?.GetComponent<StoryState>();
            if (storyState != null && storyState.GetFlag("escaped_countermeasures"))
            {
                CompleteObjective(objective.ID);
                Debug.Log("����������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������Objective completed: Escape increasing Mark system countermeasures");
            }
        }
    }

    // Helper method to find objective by description
    private MissionObjective GetObjectiveByDescription(string description)
    {
        return Objectives.FirstOrDefault(obj => obj.Description == description);
    }

    public override void OnMissionCompleted()
    {
        base.OnMissionCompleted();
        Debug.Log("��������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������");_END: REVELATION  ���������������������������������� ������������������������������� ������������������������������� ������������������������������� ������������������������������� ������������������������������� ������������������������������� ������������������������������� ������������������������������� ������������������������������� ������������������������������� ������������������������������� ������������������������������� ������������������������������� ������������������������������� ������������������������������� �������������������������������� ������������������������������ ����������������������������� ����������������������������� ����������������������������� ����������������������������� ����������������������������� ����������������������������� ����������������������������� ����������������������������� ����������������������������� �����������������������